import sys
from collections import deque

input = sys.stdin.read().split()
K = int(input[0])
P = list(map(int, input[1:K+1]))
matrix = [input[K+1+i] for i in range(K)]

graph = {i: [] for i in range(K)}
for i in range(K):
    for j in range(K):
        if matrix[i][j] == 'Y':
            graph[i].append(j)

visited = [False] * K
result = [0] * K

def bfs(start):
    queue = deque([start])
    visited[start] = True
    group = []
    while queue:
        node = queue.popleft()
        group.append(node)
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)
    return group

for i in range(K):
    if not visited[i]:
        group = bfs(i)
        indices = sorted(group)
        values = sorted(P[j] for j in group)
        for idx, val in zip(indices, values):
            result[idx] = val

print(' '.join(map(str, result)))
